interface Params {
	weightKg: number;
	isExpress: boolean;
	destination: { ratePerKg: number; expressSurcharge: number; minimumCharge: number };
}

// One exit, so the floor is written once and applies to every path.
export const calculateShippingCost = ({ weightKg, isExpress, destination }: Params): number => {
	let cost = weightKg * destination.ratePerKg;

	if (isExpress) {
		cost += destination.expressSurcharge;
	}

	if (cost < destination.minimumCharge) {
		cost = destination.minimumCharge;
	}

	return cost;
};

interface Params {
	weightKg: number;
	isExpress: boolean;
	destination: { ratePerKg: number; expressSurcharge: number; minimumCharge: number };
}

// A return per branch, so the minimum-charge floor has to be remembered three
// times — and the express branch is where it was forgotten.
export const calculateShippingCost = ({ weightKg, isExpress, destination }: Params): number => {
	if (isExpress) {
		return weightKg * destination.ratePerKg + destination.expressSurcharge;
	}

	if (weightKg * destination.ratePerKg < destination.minimumCharge) {
		return destination.minimumCharge;
	}

	return weightKg * destination.ratePerKg;
};

// Genuinely computed — it has a moving part (an identifier), so it is not a
// folded number, however many places read it.
const startedAt = Date.now();

// A folded number read in two places has earned its module scope.
const graceWindowMs = 5 * 60_000;

const isWithinGrace = ({ elapsedMs }: { elapsedMs: number }) => elapsedMs < graceWindowMs;

export const buildReceipt = ({ elapsedMs }: { elapsedMs: number }): string =>
	`started ${startedAt}, grace ${graceWindowMs}, within: ${isWithinGrace({ elapsedMs })}`;

export const chargeInvoice = ({ attempt }: { attempt: number }): boolean => {
	const maxRetries = 10;

	return attempt < maxRetries;
};

// A lookup map, which the rule names as its other carve-out.
export const chargeLabels: Record<string, string> = {
	paid: 'Paid',
	due: 'Due',
};

// Consumed in two places, which is exactly what earns module scope.
const maxAttempts = 3;

const isFinalAttempt = ({ attempt }: { attempt: number }) => attempt >= maxAttempts;

export const retryCharge = ({ attempt }: { attempt: number }): boolean => attempt < maxAttempts && !isFinalAttempt({ attempt });

const maxRetries = 10;

// A folded number names a value the same way a bare literal does.
const retryWindowMs = 10 * 60_000;

export const chargeInvoice = ({ attempt, elapsedMs }: { attempt: number; elapsedMs: number }): boolean => attempt < maxRetries && elapsedMs < retryWindowMs;

// A lone name may use any verb: nothing else in the repo names this concept,
// so there is no pair and nothing to report.
export const readFile = ({ path }: { path: string }): string => `contents of ${path}`;

// The framework pair the rule spares: a route segment and the component that
// renders it, one name spelled for two conventions.
export const route = '/get-started';

